// Author: MiYu. Source AI natives consume live units, paid orders, queues, resources and captain goals.
#include "session.h"
#include <algorithm>
#include <bit>
#include <cmath>

namespace war3 {
namespace {float number(jass::Real value){return std::bit_cast<float>(value.bits());}jass::Real real(float value){return jass::Real::fromBits(std::bit_cast<std::uint32_t>(value));}float distance(WorldPoint a,WorldPoint b){return std::hypot(number(a.x)-number(b.x),number(a.y)-number(b.y));}int integer(jass::Value value){return std::bit_cast<int>(value.bits);}}
void ScriptSession::bindAiRuntime(ScriptAI& ai){
    auto bind=[&](const char* name,const char* result,std::initializer_list<const char*> parameters,jass::Runtime::Native native){auto& vm=*ai.runtime;auto id=vm.module().functionId(name);if(id==jass::none)return;auto& signature=vm.module().functions()[id];if(!vm.module().program().functions()[id].native || vm.module().type(signature.result).name!=result || signature.parameters.size()!=parameters.size())throw std::runtime_error(std::string("Invalid AI native signature: ")+name);size_t i=0;for(auto type:parameters)if(vm.module().type(signature.parameters[i++]).name!=type)throw std::runtime_error(std::string("Invalid AI native parameter: ")+name);vm.bind(name,std::move(native));};
    bind("Sleep","nothing",{"real"},[](auto& vm,auto args){vm.sleep(std::bit_cast<float>(args[0].bits));return vm.nothing();});
    bind("StartThread","nothing",{"code"},[](auto& vm,auto args){vm.start(args[0]);return vm.nothing();});
    auto owned=[this,&ai](bool combat=false){std::vector<std::uint32_t> result;for(auto& [id,u]:units_)if(u->owner==ai.owner && !u->removing && !u->hidden() && !u->construction && number(u->life)>0 && (!combat || (!u->building && u->buildables.empty() && hasWeapon(id) && !ai.guardUnits.contains(id) && !ai.suicideUnits.contains(id) && (ai.groupTimedLife || !u->timedLife))))result.push_back(id);return result;};
    bind("GetAiPlayer","integer",{},[&ai](auto& vm,auto){return vm.integer(int(ai.owner));});
    bind("MeleeDifficulty","integer",{},[this,&ai](auto& vm,auto){return vm.integer(int(config_.players[ai.owner].difficulty)+1);});
    bind("GetHeroId","integer",{},[this,&ai](auto& vm,auto){return vm.integer(ai.hero && alive(ai.hero,NativeKind::Unit)?int(units_.at(ai.hero)->type):0);});
    bind("GetHeroLevelAI","integer",{},[this,&ai](auto& vm,auto){return vm.integer(ai.hero && alive(ai.hero,NativeKind::Unit)?units_.at(ai.hero)->level:0);});
    bind("SetHeroLevels","nothing",{"code"},[&ai](auto& vm,auto args){ai.heroLevels=args[0];return vm.nothing();});
    for(auto [name,done]:std::initializer_list<std::pair<const char*,bool>>{{"GetUnitCount",false},{"GetUnitCountDone",true}})bind(name,"integer",{"integer"},[this,&ai,done](auto& vm,auto args){return vm.integer(int(aiCount(ai,args[0].bits,done)));});
    bind("GetPlayerUnitTypeCount","integer",{"player","integer"},[this](auto& vm,auto args){auto owner=playerId(args[0]);unsigned count=0;for(auto& [id,u]:units_)if(u->owner==owner && u->type==args[1].bits && !u->removing && number(u->life)>0)++count;return vm.integer(int(count));});
    bind("GetTownUnitCount","integer",{"integer","integer","boolean"},[this,&ai](auto& vm,auto args){return vm.integer(int(aiCount(ai,args[0].bits,args[2].bits!=0,integer(args[1]))));});
    for(auto [name,kind]:std::initializer_list<std::pair<const char*,unsigned>>{{"GetUnitGoldCost",0},{"GetUnitWoodCost",1},{"GetUnitBuildTime",2}})bind(name,"integer",{"integer"},[this,kind](auto& vm,auto args){auto& info=product(args[0].bits);return vm.integer(kind==0?info.gold:kind==1?info.lumber:int(info.trainTime));});
    bind("SetProduce","boolean",{"integer","integer","integer"},[this,&ai](auto& vm,auto args){return vm.boolean(integer(args[0])>0 && aiProduce(ai,args[0].bits,args[1].bits,integer(args[2])));});
    bind("SetUpgrade","boolean",{"integer"},[this,&ai](auto& vm,auto args){return vm.boolean(aiUpgrade(ai,args[0].bits));});
    bind("MergeUnits","boolean",{"integer","integer","integer","integer"},[this,&ai](auto& vm,auto args){return vm.boolean(aiMergeUnits(ai,integer(args[0]),args[1].bits,args[2].bits,args[3].bits));});
    bind("ConvertUnits","boolean",{"integer","integer"},[this,&ai](auto& vm,auto args){return vm.boolean(aiConvertUnits(ai,integer(args[0]),args[1].bits));});
    bind("PurchaseZeppelin","nothing",{},[this,&ai](auto& vm,auto){aiPurchaseZeppelin(ai);return vm.nothing();});
    bind("LoadZepWave","nothing",{"integer","integer"},[this,&ai](auto& vm,auto args){aiCancelCaptainRoute(ai);aiLoadZeppelinWave(ai,{real(float(integer(args[0]))),real(float(integer(args[1])))});return vm.nothing();});
    bind("GetUpgradeLevel","integer",{"integer"},[this,&ai](auto& vm,auto args){return vm.integer(int(researchLevel(ai.owner,args[0].bits)));});
    for(auto [name,wood]:std::initializer_list<std::pair<const char*,bool>>{{"GetUpgradeGoldCost",false},{"GetUpgradeWoodCost",true}})bind(name,"integer",{"integer"},[this,&ai,wood](auto& vm,auto args){auto& info=researchInfo(args[0].bits,researchLevel(ai.owner,args[0].bits)+1);return vm.integer(wood?info.product.lumber:info.product.gold);});
    bind("GetMinesOwned","integer",{},[this,&ai](auto& vm,auto){std::set<std::uint32_t> mines;for(size_t town=0;town<ai.towns.size();++town)if(auto mine=aiMine(ai,int(town)))mines.insert(mine);return vm.integer(int(mines.size()));});
    bind("GetGoldOwned","integer",{},[this,&ai](auto& vm,auto){std::set<std::uint32_t> mines;for(size_t town=0;town<ai.towns.size();++town)if(auto mine=aiMine(ai,int(town)))mines.insert(mine);std::int64_t gold=0;for(auto id:mines)gold+=units_.at(id)->resources;return vm.integer(int(std::min<std::int64_t>(gold,INT_MAX)));});
    bind("TownWithMine","integer",{},[this,&ai](auto& vm,auto){for(size_t town=0;town<ai.towns.size();++town)if(aiMine(ai,int(town)))return vm.integer(int(town));return vm.integer(-1);});
    bind("TownHasMine","boolean",{"integer"},[this,&ai](auto& vm,auto args){return vm.boolean(integer(args[0])>=0 && aiMine(ai,integer(args[0]))!=0);});
    bind("TownHasHall","boolean",{"integer"},[this,&ai](auto& vm,auto args){auto town=integer(args[0]);return vm.boolean(town>=0 && size_t(town)<ai.towns.size() && alive(ai.towns[town],NativeKind::Unit) && units_.at(ai.towns[town])->owner==ai.owner && number(units_.at(ai.towns[town])->life)>0);});
    for(auto [name,wood]:std::initializer_list<std::pair<const char*,bool>>{{"HarvestGold",false},{"HarvestWood",true}})bind(name,"nothing",{"integer","integer"},[this,&ai,wood](auto& vm,auto args){auto town=integer(args[0]),count=integer(args[1]);if(town< -1 || town>=16 || count<0 || count>128)throw std::runtime_error("AI harvest goals exceed limits");ai.gathering=true;auto& goal=ai.harvesting[town];auto& assigned=wood?goal.second:goal.first;if(assigned>128-count)throw std::runtime_error("AI harvest total exceeds limit");assigned+=count;return vm.nothing();});
    bind("ClearHarvestAI","nothing",{},[&ai](auto& vm,auto){ai.harvesting.clear();return vm.nothing();});
    bind("StopGathering","nothing",{},[this,&ai,owned](auto& vm,auto){ai.gathering=false;for(auto id:owned())if(alive(id,NativeKind::Unit) && units_.at(id)->gather.phase!=GatherOrder::Phase::None)stopUnit(id);return vm.nothing();});
    for(auto [name,campaign]:std::initializer_list<std::pair<const char*,bool>>{{"SetMeleeAI",false},{"SetCampaignAI",true}})bind(name,"nothing",{},[&ai,campaign](auto& vm,auto){ai.campaign=campaign;return vm.nothing();});
    bind("SetAmphibious","nothing",{},[&ai](auto& vm,auto){ai.amphibious=true;return vm.nothing();});
    for(auto [name,policy]:std::initializer_list<std::pair<const char*,ScriptAI::Policy>>{{"SetDefendPlayer",ScriptAI::DefendPlayer},{"SetGroupsFlee",ScriptAI::GroupsFlee},{"SetHeroesBuyItems",ScriptAI::HeroesBuy},{"SetHeroesFlee",ScriptAI::HeroesFlee},{"SetHeroesTakeItems",ScriptAI::HeroesTake},{"SetIgnoreInjured",ScriptAI::IgnoreInjured},{"SetPeonsRepair",ScriptAI::PeonsRepair},{"SetSmartArtillery",ScriptAI::SmartArtillery},{"SetTargetHeroes",ScriptAI::TargetHeroes},{"SetUnitsFlee",ScriptAI::UnitsFlee},{"SetWatchMegaTargets",ScriptAI::WatchMega}})bind(name,"nothing",{"boolean"},[&ai,policy](auto& vm,auto args){ai.policies[policy]=args[0].bits!=0;return vm.nothing();});
    bind("CreateCaptains","nothing",{},[this,&ai](auto& vm,auto){aiCancelCaptainRoute(ai);aiCancelZeppelinWave(ai);ai.captain.clear();ai.defenderUnits.clear();ai.assault.clear();ai.defenders.clear();ai.homeOverride=false;aiTowns(ai);ai.stage=ai.goal=ai.home;ai.retreating=false;return vm.nothing();});
    bind("InitAssault","nothing",{},[this,&ai](auto& vm,auto){aiCancelCaptainRoute(ai);aiCancelZeppelinWave(ai);ai.assault.clear();ai.captain.clear();return vm.nothing();});
    for(auto [name,defense]:std::initializer_list<std::pair<const char*,bool>>{{"AddAssault",false},{"AddDefenders",true}})bind(name,"boolean",{"integer","integer"},[this,&ai,defense](auto& vm,auto args){auto desired=integer(args[0]);if(desired<0 || desired>1024)throw std::runtime_error("AI captain request exceeds limit");auto type=args[1].bits;auto& demands=defense?ai.defenders:ai.assault;demands[type]=unsigned(desired);aiFormCaptains(ai,true);unsigned count=0;for(auto id:defense?ai.defenderUnits:ai.captain)if(alive(id,NativeKind::Unit) && units_.at(id)->type==type)++count;return vm.boolean(count>=unsigned(desired));});
    bind("RemoveInjuries","nothing",{},[this,&ai](auto& vm,auto){for(auto it=ai.captain.begin();it!=ai.captain.end();)if(!alive(*it,NativeKind::Unit) || number(units_.at(*it)->life)<number(units_.at(*it)->maxLife)*.5f)it=ai.captain.erase(it);else ++it;return vm.nothing();});
    bind("RemoveSiege","nothing",{},[this,&ai](auto& vm,auto){for(auto it=ai.captain.begin();it!=ai.captain.end();)if(!alive(*it,NativeKind::Unit) || unitWeapon(*units_.at(*it),0).attackType==2)it=ai.captain.erase(it);else ++it;return vm.nothing();});
    bind("CaptainGroupSize","integer",{},[this,&ai](auto& vm,auto){return vm.integer(int(aiCaptain(ai).size()));});
    bind("CaptainIsEmpty","boolean",{},[this,&ai](auto& vm,auto){return vm.boolean(aiCaptain(ai).empty() && !ai.zeppelinWave);});
    bind("CaptainIsFull","boolean",{},[this,&ai](auto& vm,auto){std::map<std::uint32_t,unsigned> have;for(auto id:aiCaptain(ai))++have[units_.at(id)->type];for(auto [type,count]:ai.assault)if(have[type]<count)return vm.boolean(false);return vm.boolean(!ai.assault.empty());});
    for(auto [name,mana]:std::initializer_list<std::pair<const char*,bool>>{{"CaptainReadiness",false},{"CaptainReadinessHP",false},{"CaptainReadinessMa",true}})bind(name,"integer",{},[this,&ai,mana](auto& vm,auto){float have=0,total=0;for(auto id:aiCaptain(ai)){auto u=units_.at(id);have+=number(mana?u->mana:u->life);total+=number(mana?u->maxMana:u->maxLife);}return vm.integer(total>0?int(have*100/total):mana?100:0);});
    bind("CaptainRetreating","boolean",{},[&ai](auto& vm,auto){return vm.boolean(ai.retreating);});
    for(auto [name,home]:std::initializer_list<std::pair<const char*,bool>>{{"CaptainIsHome",true},{"CaptainAtGoal",false}})bind(name,"boolean",{},[this,&ai,home](auto& vm,auto){if(ai.zeppelinWave)return vm.boolean(false);for(auto id:aiCaptain(ai)){auto u=units_.at(id);if(distance({u->x,u->y},home?ai.home:ai.goal)>350)return vm.boolean(false);}return vm.boolean(true);});
    bind("CaptainInCombat","boolean",{"boolean"},[this,&ai,owned](auto& vm,auto args){auto ids=args[0].bits?aiCaptain(ai):owned(true);for(auto id:ids)if(units_.at(id)->combat.target)return vm.boolean(true);return vm.boolean(false);});
    bind("CaptainGoHome","nothing",{},[this,&ai](auto& vm,auto){aiCancelCaptainRoute(ai);aiCancelZeppelinWave(ai);ai.retreating=true;ai.goal=ai.home;for(auto id:aiCaptain(ai))moveUnit(id,ai.home);return vm.nothing();});
    bind("SetCaptainHome","nothing",{"integer","real","real"},[&ai](auto& vm,auto args){if(args[0].bits>1)throw std::runtime_error("Unknown AI captain");ai.home={jass::Real::fromBits(args[1].bits),jass::Real::fromBits(args[2].bits)};ai.homeOverride=true;return vm.nothing();});
    bind("SetStagePoint","nothing",{"real","real"},[this,&ai](auto& vm,auto args){aiCancelCaptainRoute(ai);ai.stage={jass::Real::fromBits(args[0].bits),jass::Real::fromBits(args[1].bits)};ai.goal=ai.stage;return vm.nothing();});
    bind("CaptainAttack","nothing",{"real","real"},[this,&ai](auto& vm,auto args){aiAttack(ai,{jass::Real::fromBits(args[0].bits),jass::Real::fromBits(args[1].bits)});return vm.nothing();});
    bind("AttackMoveXY","nothing",{"integer","integer"},[this,&ai](auto& vm,auto args){aiAttack(ai,{real(float(integer(args[0]))),real(float(integer(args[1])))});return vm.nothing();});
    bind("AttackMoveKill","nothing",{"unit"},[this,&ai](auto& vm,auto args){if(args[0].bits && alive(args[0].bits,NativeKind::Unit)){auto u=units_.at(args[0].bits);aiAttack(ai,{u->x,u->y},args[0].bits);}return vm.nothing();});
    for(auto name:{"CaptainVsPlayer","CaptainVsUnits"})bind(name,"nothing",{"player"},[this,&ai](auto& vm,auto args){if(auto target=aiEnemy(ai,playerId(args[0]))){auto u=units_.at(target);aiAttack(ai,{u->x,u->y},target);}return vm.nothing();});
    for(auto [name,buildings]:std::initializer_list<std::pair<const char*,bool>>{{"SuicidePlayer",true},{"SuicidePlayerUnits",false}})bind(name,"boolean",{"player","boolean"},[this,&ai,buildings](auto& vm,auto args){auto target=aiEnemy(ai,playerId(args[0]),buildings);if(!target)return vm.boolean(false);if(args[1].bits)for(auto [type,qty]:ai.assault)if(aiCount(ai,type,true)<qty)return vm.boolean(false);auto u=units_.at(target);aiAttack(ai,{u->x,u->y},target);return vm.boolean(true);});
    bind("GetBuilding","unit",{"player"},[this,&ai](auto& vm,auto args){auto owner=playerId(args[0]);std::uint32_t chosen=0;float nearest=FLT_MAX;for(auto& [id,u]:units_)if(u->owner==owner && u->building && !u->removing && !u->hidden() && !u->unsummon && number(u->life)>0){auto d=distance(ai.home,{u->x,u->y});if(d<nearest){chosen=id;nearest=d;}}return vm.handle("unit",chosen);});
    bind("StartGetEnemyBase","nothing",{},[this,&ai](auto& vm,auto){ai.enemyBase=aiEnemy(ai,UINT_MAX,true);return vm.nothing();});
    bind("WaitGetEnemyBase","boolean",{},[this,&ai](auto& vm,auto){return vm.boolean(alive(ai.enemyBase,NativeKind::Unit));});
    bind("GetEnemyBase","unit",{},[this,&ai](auto& vm,auto){if(!alive(ai.enemyBase,NativeKind::Unit))ai.enemyBase=aiEnemy(ai,UINT_MAX,true);return vm.handle("unit",ai.enemyBase);});
    bind("GetMegaTarget","unit",{},[this,&ai](auto& vm,auto){auto target=aiEnemy(ai,UINT_MAX,true);if(target){auto owner=units_.at(target)->owner;unsigned defenders=0;for(auto& [id,u]:units_)if(u->owner==owner && !u->building && !u->removing && number(u->life)>0 && hasWeapon(id))++defenders;if(defenders>=aiCaptain(ai).size())target=0;}return vm.handle("unit",target);});
    bind("SetAllianceTarget","nothing",{"unit"},[&ai](auto& vm,auto args){ai.allianceTarget=args[0].bits;return vm.nothing();});
    bind("GetAllianceTarget","unit",{},[this,&ai](auto& vm,auto){for(auto& ally:ais_)if(ally && ally->owner!=ai.owner && (config_.players[ai.owner].alliances[ally->owner]&1) && alive(ally->allianceTarget,NativeKind::Unit))return vm.handle("unit",ally->allianceTarget);return vm.handle("unit",0);});
    bind("TownThreatened","boolean",{},[this,&ai](auto& vm,auto){auto target=aiEnemy(ai);return vm.boolean(target && distance(ai.home,{units_.at(target)->x,units_.at(target)->y})<1200);});
    bind("GetCreepCamp","unit",{"integer","integer","boolean"},[this,&ai](auto& vm,auto args){std::uint32_t result=0;float best=FLT_MAX;std::set<std::uint32_t> visited;for(auto& [id,u]:units_)if(u->owner==12 && !u->removing && !u->hidden() && !u->invulnerable && number(u->life)>0 && !visited.contains(id)){int level=0;bool flying=false;for(auto& [memberId,member]:units_)if(member->owner==12 && !member->removing && number(member->life)>0 && distance({u->x,u->y},{member->x,member->y})<600){visited.insert(memberId);level+=member->level;flying=flying || member->movementType=="fly";}if(level<integer(args[0]) || level>integer(args[1]) || (flying && !args[2].bits))continue;auto d=distance(ai.home,{u->x,u->y});if(d<best){best=d;result=id;}}return vm.handle("unit",result);});
    bind("CreepsOnMap","boolean",{},[this](auto& vm,auto){for(auto& [id,u]:units_)if(u->owner==12 && !u->removing && !u->invulnerable && number(u->life)>0)return vm.boolean(true);return vm.boolean(false);});
    bind("UnitAlive","boolean",{"unit"},[this](auto& vm,auto args){return vm.boolean(alive(args[0].bits,NativeKind::Unit) && !units_.at(args[0].bits)->removing && number(units_.at(args[0].bits)->life)>0);});
    auto expansion=[this,&ai](){std::uint32_t result=0;float best=FLT_MAX;for(auto& [id,u]:units_)if(!u->removing && !u->hidden() && number(u->life)>0 && u->owner>=12 && u->resources>0 && sourceAbility(*u,"Agld").first){bool occupied=false;for(auto hall:ai.towns)if(alive(hall,NativeKind::Unit) && number(units_.at(hall)->life)>0 && distance({u->x,u->y},{units_.at(hall)->x,units_.at(hall)->y})<1600){occupied=true;break;}auto d=distance(ai.home,{u->x,u->y});if(!occupied && d<best){best=d;result=id;}}ai.expansion=result;return result;};
    bind("GetNextExpansion","integer",{},[&ai,expansion](auto& vm,auto){return vm.integer(expansion()?int(ai.towns.size()):-1);});
    for(auto [name,x]:std::initializer_list<std::pair<const char*,bool>>{{"GetExpansionX",true},{"GetExpansionY",false}})bind(name,"integer",{},[this,&ai,expansion,x](auto& vm,auto){if(!alive(ai.expansion,NativeKind::Unit))expansion();if(!ai.expansion)return vm.integer(0);auto u=units_.at(ai.expansion);return vm.integer(int(number(x?u->x:u->y)));});
    bind("GetExpansionPeon","unit",{},[this,&ai,owned](auto& vm,auto){std::uint32_t result=0;float best=FLT_MAX;WorldPoint goal=ai.home;if(alive(ai.expansion,NativeKind::Unit))goal={units_.at(ai.expansion)->x,units_.at(ai.expansion)->y};for(auto id:owned()){auto u=units_.at(id);if(u->buildables.empty() || u->workingOn || u->buildOrder || ai.reservesUnit(id))continue;auto d=distance(goal,{u->x,u->y});if(d<best){best=d;result=id;}}return vm.handle("unit",result);});
    bind("SetExpansion","boolean",{"unit","integer"},[this,&ai,expansion](auto& vm,auto args){if(!alive(args[0].bits,NativeKind::Unit) || units_.at(args[0].bits)->owner!=ai.owner)return vm.boolean(false);if(!alive(ai.expansion,NativeKind::Unit))expansion();if(!ai.expansion)return vm.boolean(false);auto mine=units_.at(ai.expansion);for(unsigned side=0;side<16;++side){float angle=float(side)*6.28318530718f/16;if(build(args[0].bits,args[1].bits,{real(number(mine->x)+std::cos(angle)*512),real(number(mine->y)+std::sin(angle)*512)}))return vm.boolean(true);}return vm.boolean(false);});
    bind("GetExpansionFoe","unit",{},[this,&ai,expansion](auto& vm,auto){if(!alive(ai.expansion,NativeKind::Unit))expansion();if(!ai.expansion)return vm.handle("unit",0);auto mine=units_.at(ai.expansion);for(auto& [id,u]:units_)if(u->owner!=ai.owner && !(config_.players[ai.owner].alliances[u->owner]&1) && !u->removing && !u->hidden() && !u->invulnerable && number(u->life)>0 && distance({mine->x,mine->y},{u->x,u->y})<700 && hasWeapon(id))return vm.handle("unit",id);return vm.handle("unit",0);});
    bind("GetEnemyExpansion","unit",{},[this,&ai](auto& vm,auto){std::map<unsigned,unsigned> halls;for(auto& [id,u]:units_)if(u->owner<12 && u->owner!=ai.owner && !u->removing && number(u->life)>0 && u->classifications(definitions().unitClasses(u->type)).find("townhall")!=std::string::npos && !(config_.players[ai.owner].alliances[u->owner]&1))if(++halls[u->owner]>1)return vm.handle("unit",id);return vm.handle("unit",0);});
    bind("GetEnemyPower","integer",{},[this,&ai](auto& vm,auto){unsigned power=0;for(auto& [id,u]:units_)if(u->owner<12 && enemy(ai.owner,u->owner) && !u->removing && !u->hidden() && number(u->life)>0 && hasWeapon(id))power+=unsigned(std::max(1,u->foodUsed));return vm.integer(int(power));});
    bind("IsTowered","boolean",{"unit"},[this](auto& vm,auto args){if(!alive(args[0].bits,NativeKind::Unit))return vm.boolean(false);auto target=units_.at(args[0].bits);for(auto& [id,u]:units_)if(u->owner==target->owner && u->building && !u->removing && number(u->life)>0 && hasWeapon(id) && distance({target->x,target->y},{u->x,u->y})<900)return vm.boolean(true);return vm.boolean(false);});
    bind("CommandsWaiting","integer",{},[&ai](auto& vm,auto){return vm.integer(int(ai.commands.size()));});
    for(auto [name,data]:std::initializer_list<std::pair<const char*,bool>>{{"GetLastCommand",false},{"GetLastData",true}})bind(name,"integer",{},[&ai,data](auto& vm,auto){if(ai.commands.empty())throw std::runtime_error("Empty AI command queue");return vm.integer(data?ai.commands.front().second:ai.commands.front().first);});
    bind("PopLastCommand","nothing",{},[&ai](auto& vm,auto){if(ai.commands.empty())throw std::runtime_error("Empty AI command queue");ai.commands.pop_front();return vm.nothing();});
    bind("DoAiScriptDebug","boolean",{},[](auto& vm,auto){return vm.boolean(false);});
    for(auto name:{"DebugS","DebugFI","DebugUnitID","DisplayText","DisplayTextI","DisplayTextII","DisplayTextIII"}){auto id=ai.runtime->module().functionId(name);if(id==jass::none)continue;ai.runtime->bind(name,[this,&ai,name=std::string(name)](auto& vm,auto args){std::string text;for(auto& arg:args)text+=arg.text?*arg.text:std::to_string(integer(arg));if(ai.diagnostics.size()>=128)ai.diagnostics.erase(ai.diagnostics.begin());ai.diagnostics.push_back(text);if(name.starts_with("Display"))displayText(args[0].bits,0,0,5,text);return vm.nothing();});}
}
}
